/**
 * 舊試算表帶過來的「改善檔案」連結稽核（系統維護）
 *   以雲端硬碟檔案內容（MD5）比對系統內已歸檔的改善檔：
 *   同案已有 → 舊連結多餘；屬其他案件 → 舊連結掛錯；僅舊連結 → 系統內尚無此檔
 *   args.apply：清除「同案已有」「屬其他案件」的舊連結
 */
function apiImpLegacy(args, user) {
  const idCase = {}; readTable_('紀錄檔').filter(r => r.種類 === IMP_KIND).forEach(r => { idCase[String(r.檔案ID)] = String(r.案件編號); });
  const md5Of = {};
  impSrcFiles_(impFolder_(), '', [], 9).forEach(f => { if (f.md5 && idCase[f.id]) (md5Of[f.md5] = md5Of[f.md5] || []).push(idCase[f.id]); });
  const out = [], t0 = Date.now(), now = nowStr_();
  readTable_('案件').filter(c => /^https?:\/\//i.test(String(c.改善檔案 || ''))).forEach(c => {
    if (Date.now() - t0 > 250000) return;
    const m = String(c.改善檔案).match(/[-\w]{25,}/);
    let md5 = '', name = '', err = '';
    if (m) { try { const j = JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files/' + m[0] + '?fields=name,md5Checksum&supportsAllDrives=true').getContentText()); md5 = j.md5Checksum || ''; name = j.name || ''; } catch (e) { err = e.message.slice(0, 80); } }
    const owners = (md5Of[md5] || []).filter((x, i, a) => a.indexOf(x) === i);
    const kind = !m ? '非雲端連結' : err ? '無法讀取' : owners.indexOf(String(c.案件編號)) >= 0 ? '同案已有' : owners.length ? '屬其他案件' : '僅舊連結';
    const row = { id: c.案件編號, 日期: c.日期, 項目: c.項目, 工程名稱: c.工程名稱, 狀態: c.狀態, 檔名: name, 類型: kind, 實際案件: owners.join(','), 錯誤: err };
    if (args.apply && (kind === '同案已有' || kind === '屬其他案件')) {
      const old = c.改善檔案; c.改善檔案 = ''; c.修改者 = user.Email; c.修改時間 = now; writeRow_('案件', c);
      log_(user.Email, '清除舊改善檔連結', c.案件編號, { 原因: kind, 實際案件: row.實際案件, 原連結: old });
      row.已清除 = true;
    }
    out.push(row);
  });
  return out;
}
  impLegacy: [apiImpLegacy, ['系統維護']],
